// ============================================================================
// PARSER CENTRAL DE RESULTADOS OFICIALES - BANCA EL CASTAÑO
// Extrae, limpia y clasifica en: SIN SIGNO, CON SIGNO, 4 CIFRAS y ANIMALITOS
// ============================================================================

const now = new Date();
const fechaISO = now.toISOString().split('T')[0];

const htmlTriples = $('1. TuAzar Triples y Signos').first()?.json?.data || '';
const htmlAnimalitos = $('2. TuAzar Animalitos').first()?.json?.data || '';
const htmlFrutas = $('3. TuAzar Fruta Gana').first()?.json?.data || '';
const htmlColombia = $('4. Loterias Colombia (4 Cifras y 5ta)').first()?.json?.data || '';

const resultados = [];

// Diccionario auxiliar de signos zodiacales
const signosRegex = /\b(ARI|TAU|GEM|CAN|LEO|VIR|LIB|ESC|SAG|CAP|ACU|PIS|ARIES|TAURO|GEMINIS|GÉMINIS|CANCER|CÁNCER|VIRGO|LIBRA|ESCORPIO|SAGITARIO|CAPRICORNIO|ACUARIO|PISCIS)\b/i;

// Función para limpiar etiquetas HTML
const cleanText = (str) => str.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();

// 1. PARSEAR ANIMALITOS Y FRUTA GANA
function parseBlocks(html, defaultCategory, isFruit = false) {
  if (!html) return;
  // Busca bloques de horario (ej: 8:00 AM, 10:30 AM, 12:05 PM) y su número/nombre cercano
  const regexHora = /(\d{1,2}:\d{2}\s*(?:AM|PM))/gi;
  let match;
  while ((match = regexHora.exec(html)) !== null) {
    const hora = match[1].toUpperCase().replace(/\s+/g, ' ');
    const start = Math.max(0, match.index - 350);
    const end = Math.min(html.length, match.index + 350);
    const snippet = cleanText(html.substring(start, end));

    // Detectar operadora en el contexto
    let operadora = isFruit ? 'Fruta Gana' : null;
    const ops = [
      'Lotto Activo RD', 'Lotto Activo', 'La Granjita', 'Monje Millonario',
      'Guacharito Millonario', 'Guácharo Activo', 'Guacharo Activo',
      'Selva Plus', 'Ruleta Royal', 'Loto Chaima', 'Granjazo',
      'Granja Millonaria', 'Fieras', 'Bichitos', 'Mascotas',
      'Chance con Animalitos B', 'Chance con Animalitos', 'Gatazo',
      'Lotto Gato', 'Mega Animal 40', 'Triple Popular', 'Tropi Gana',
      'El Arrejuntao'
    ];
    if (!operadora) {
      for (const op of ops) {
        if (snippet.toUpperCase().includes(op.toUpperCase())) {
          operadora = op;
          break;
        }
      }
    }

    // Buscar patrón de resultado tipo "00 - BALLENA" o "28 COCO"
    const numMatch = snippet.match(/\b(00|\d{1,2})\s*[-–:]?\s*([A-ZÁÉÍÓÚÑ]{3,14})\b/i);
    if (operadora && numMatch && !['HORA', 'SORTEO', 'RESULTADO', 'AYER', 'HOY'].includes(numMatch[2].toUpperCase())) {
      const codigo = numMatch[1];
      const figura = numMatch[2].toUpperCase();
      const idUnico = `${operadora}_${hora}`.replace(/\s+/g, '_').toUpperCase();

      if (!resultados.some(r => r.id === idUnico)) {
        resultados.push({
          id: idUnico,
          fecha: fechaISO,
          categoria: 'ANIMALITOS',
          loteria: `${operadora} ${hora}`,
          horaSorteo: hora,
          numero: codigo,
          complemento: figura,
          resultadoOficial: `${codigo} (${figura})`,
          origen: 'AUTO-WEB OFICIAL',
          verificado: true
        });
      }
    }
  }
}

parseBlocks(htmlAnimalitos, 'ANIMALITOS', false);
parseBlocks(htmlFrutas, 'ANIMALITOS', true);

// 2. PARSEAR TRIPLES Y SIGNOS VENEZUELA
if (htmlTriples) {
  const regexTripleRow = /(\d{1,2}:\d{2}\s*(?:AM|PM))[\s\S]{1,400}?\b(\d{3,5})\b(?:\s*(ARI|TAU|GEM|CAN|LEO|VIR|LIB|ESC|SAG|CAP|ACU|PIS))?/gi;
  let m;
  while ((m = regexTripleRow.exec(htmlTriples)) !== null) {
    const hora = m[1].toUpperCase().replace(/\s+/g, ' ');
    const numero = m[2];
    const signo = m[3] ? m[3].toUpperCase() : null;
    const cat = signo ? 'CON SIGNO' : (numero.length >= 4 ? '4 CIFRAS' : 'SIN SIGNO');
    const contexto = cleanText(htmlTriples.substring(Math.max(0, m.index - 500), m.index));

    let nombreLot = 'Triple Oficial';
    const lots = [
      'Triple Táchira', 'Triple Zulia', 'Chance en Línea', 'Triple Caliente',
      'Triple Lago', 'Triple Gato', 'El Arrejuntao', 'Triple Zamorano',
      'La Ricachona', 'Triple Fácil', 'Trío Activo', 'Triple Popular',
      'Triple Dorado', 'Triple Fortuna', 'Super Gana', 'Triple Gana', 'Ñapa Gana'
    ];
    for (const l of lots) {
      if (contexto.toUpperCase().includes(l.toUpperCase())) {
        nombreLot = l;
        break;
      }
    }

    const idUnico = `${nombreLot}_${hora}_${cat}`.replace(/\s+/g, '_').toUpperCase();
    if (!resultados.some(r => r.id === idUnico)) {
      resultados.push({
        id: idUnico,
        fecha: fechaISO,
        categoria: cat,
        loteria: `${nombreLot} ${hora}`,
        horaSorteo: hora,
        numero: numero,
        complemento: signo || '',
        resultadoOficial: signo ? `${numero} - ${signo}` : numero,
        origen: 'AUTO-WEB OFICIAL',
        verificado: true
      });
    }
  }
}

// 3. PARSEAR LOTERÍAS DE COLOMBIA (4 CIFRAS, LA 5TA Y ASTROS)
if (htmlColombia) {
  const colLots = [
    { name: 'Bogotá', hora: '11:15 PM' },
    { name: 'Quindío', hora: '10:30 PM' },
    { name: 'Medellín', hora: '11:00 PM' },
    { name: 'Santander', hora: '11:00 PM' },
    { name: 'Boyacá', hora: '10:40 PM' },
    { name: 'Cauca', hora: '10:40 PM' },
    { name: 'Cruz Roja', hora: '10:55 PM' },
    { name: 'Huila', hora: '10:30 PM' },
    { name: 'Manizales', hora: '10:30 PM' },
    { name: 'Cundinamarca', hora: '10:30 PM' },
    { name: 'Dorado Mañana', hora: '10:55 AM' },
    { name: 'Dorado Tarde', hora: '3:30 PM' },
    { name: 'Dorado Noche', hora: '10:05 PM' },
    { name: 'Culona', hora: '2:30 PM' },
    { name: 'Culona Noche', hora: '9:30 PM' },
    { name: 'Astro Sol', hora: '2:30 PM', isSigno: true },
    { name: 'Astro Luna', hora: '10:30 PM', isSigno: true },
    { name: 'Pijao de Oro', hora: '2:00 PM' },
    { name: 'Paisita Día', hora: '1:00 PM' },
    { name: 'Paisita Noche', hora: '6:00 PM' },
    { name: 'Chontico Día', hora: '1:00 PM' },
    { name: 'Chontico Noche', hora: '7:00 PM' },
    { name: 'Cafeterito Tarde', hora: '12:00 PM' },
    { name: 'Cafeterito Noche', hora: '10:00 PM' },
    { name: 'Sinuano Día', hora: '2:30 PM' },
    { name: 'Sinuano Noche', hora: '10:30 PM' },
    { name: 'Caribeña Día', hora: '2:30 PM' },
    { name: 'Caribeña Noche', hora: '10:30 PM' },
    { name: 'Motilón Tarde', hora: '3:00 PM' },
    { name: 'Motilón Noche', hora: '9:00 PM' },
    { name: 'Fantástica Día', hora: '1:00 PM' },
    { name: 'Fantástica Noche', hora: '8:30 PM' },
    { name: 'Antioqueñita Día', hora: '10:00 AM' },
    { name: 'Antioqueñita Tarde', hora: '4:00 PM' }
  ];

  const cleanCol = cleanText(htmlColombia);
  for (const lot of colLots) {
    const idx = cleanCol.toUpperCase().indexOf(lot.name.toUpperCase());
    if (idx !== -1) {
      const fragment = cleanCol.substring(idx, idx + 140);
      const numMatch = fragment.match(/\b(\d{3,4})\b/);
      if (numMatch) {
        const num = numMatch[1];
        const quintaMatch = fragment.match(/5ta\s*:?\s*(\d)/i);
        const signoMatch = fragment.match(signosRegex);
        let comp = '';
        if (lot.isSigno && signoMatch) comp = signoMatch[1].toUpperCase();
        else if (quintaMatch) comp = `La 5ta: ${quintaMatch[1]}`;

        resultados.push({
          id: `COL_${lot.name.replace(/\s+/g, '_').toUpperCase()}`,
          fecha: fechaISO,
          categoria: lot.isSigno ? 'CON SIGNO' : '4 CIFRAS',
          loteria: `${lot.name} ${lot.hora}`,
          horaSorteo: lot.hora,
          numero: num,
          complemento: comp,
          resultadoOficial: comp ? `${num} [${comp}]` : num,
          origen: 'AUTO-WEB OFICIAL',
          verificado: true
        });
      }
    }
  }
}

return [{
  json: {
    banca: 'Banca El Castaño',
    fechaSincronizacion: now.toISOString(),
    fechaSorteo: fechaISO,
    totalResultados: resultados.length,
    resultados: resultados
  }
}];
